CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS recruitment_events(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),name VARCHAR(180) NOT NULL,slug VARCHAR(100) UNIQUE NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'draft' CHECK(status IN('draft','open','live','completed','archived')),starts_at TIMESTAMPTZ,ends_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS roles(id SMALLSERIAL PRIMARY KEY,name VARCHAR(50) UNIQUE NOT NULL);
INSERT INTO roles(name) VALUES('Super Admin'),('Admin'),('Registration Volunteer'),('Entry Volunteer'),('W1 Volunteer'),('W2 Volunteer'),('Interviewer'),('Candidate') ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS users(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),username VARCHAR(80) UNIQUE NOT NULL,email VARCHAR(180) UNIQUE NOT NULL,display_name VARCHAR(140) NOT NULL,password_hash TEXT NOT NULL,role_id SMALLINT NOT NULL REFERENCES roles(id),active BOOLEAN NOT NULL DEFAULT true,last_login_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS event_users(event_id UUID NOT NULL REFERENCES recruitment_events(id) ON DELETE CASCADE,user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,assigned_role_id SMALLINT NOT NULL REFERENCES roles(id),PRIMARY KEY(event_id,user_id));
CREATE TABLE IF NOT EXISTS domains(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),event_id UUID NOT NULL REFERENCES recruitment_events(id) ON DELETE CASCADE,name VARCHAR(100) NOT NULL,active BOOLEAN NOT NULL DEFAULT true,UNIQUE(event_id,name));
CREATE TABLE IF NOT EXISTS panels(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),event_id UUID NOT NULL REFERENCES recruitment_events(id) ON DELETE CASCADE,domain_id UUID NOT NULL REFERENCES domains(id),name VARCHAR(120) NOT NULL,active BOOLEAN NOT NULL DEFAULT true,status VARCHAR(20) NOT NULL DEFAULT 'available' CHECK(status IN('available','busy','paused','disabled')),UNIQUE(event_id,name));
CREATE TABLE IF NOT EXISTS candidates(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),event_id UUID NOT NULL REFERENCES recruitment_events(id) ON DELETE CASCADE,candidate_code VARCHAR(50) NOT NULL,name VARCHAR(160) NOT NULL,email VARCHAR(180) NOT NULL,phone VARCHAR(30) NOT NULL,college VARCHAR(180),branch VARCHAR(100),academic_year VARCHAR(40),roll_number VARCHAR(60),skills TEXT,github_url TEXT,linkedin_url TEXT,portfolio_url TEXT,motivation TEXT,status VARCHAR(30) NOT NULL DEFAULT 'registered',checked_in_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(event_id,candidate_code),UNIQUE(event_id,email),UNIQUE(event_id,phone));
CREATE TABLE IF NOT EXISTS candidate_preferences(candidate_id UUID NOT NULL REFERENCES candidates(id) ON DELETE CASCADE,domain_id UUID NOT NULL REFERENCES domains(id),priority SMALLINT NOT NULL CHECK(priority BETWEEN 1 AND 4),PRIMARY KEY(candidate_id,domain_id),UNIQUE(candidate_id,priority));
CREATE TABLE IF NOT EXISTS panel_assignments(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),panel_id UUID NOT NULL REFERENCES panels(id),interviewer_id UUID NOT NULL REFERENCES users(id),active BOOLEAN NOT NULL DEFAULT true,assigned_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS interviews(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),candidate_id UUID NOT NULL REFERENCES candidates(id),panel_id UUID NOT NULL REFERENCES panels(id),domain_id UUID NOT NULL REFERENCES domains(id),interviewer_id UUID REFERENCES users(id),status VARCHAR(20) NOT NULL DEFAULT 'scheduled' CHECK(status IN('scheduled','in_progress','completed','cancelled')),started_at TIMESTAMPTZ,completed_at TIMESTAMPTZ,technical SMALLINT CHECK(technical BETWEEN 0 AND 10),communication SMALLINT CHECK(communication BETWEEN 0 AND 10),problem_solving SMALLINT CHECK(problem_solving BETWEEN 0 AND 10),domain_knowledge SMALLINT CHECK(domain_knowledge BETWEEN 0 AND 10),feedback TEXT,total_score SMALLINT CHECK(total_score BETWEEN 0 AND 40),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS one_live_interview_per_panel ON interviews(panel_id) WHERE status='in_progress';
CREATE UNIQUE INDEX IF NOT EXISTS one_live_interview_per_candidate ON interviews(candidate_id) WHERE status='in_progress';
CREATE TABLE IF NOT EXISTS audit_logs(id BIGSERIAL PRIMARY KEY,event_id UUID REFERENCES recruitment_events(id),actor_id UUID REFERENCES users(id),action VARCHAR(100) NOT NULL,entity_type VARCHAR(60),entity_id TEXT,details JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_candidates_event_status ON candidates(event_id,status);
CREATE INDEX IF NOT EXISTS idx_interviews_candidate ON interviews(candidate_id,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_audit_event_created ON audit_logs(event_id,created_at DESC);
